from lib import *
R=[]
R.append(T(3018,"टॉर्टिला बीफ़ रोलअप लंच बॉक्स","DaVita की आहार विशेषज्ञ सारा का टॉर्टिला बीफ़ रोलअप लंच बॉक्स घर पर या सफ़र में भोजन तैयार करने का एक झटपट तरीका है। यह किडनी-अनुकूल रेसिपी कटे हुए रोस्ट बीफ़, लाल प्याज़, शिमला मिर्च, खीरे, सलाद के पत्ते और क्रीम चीज़ का मेल है, जिन्हें मैदा की टॉर्टिला में लपेटा जाता है। अंगूर और बादाम फाइबर बढ़ाते हैं और इसे पूरा भोजन बना देते हैं।","1","1 लंच बॉक्स",
["2-1/2 औंस पका हुआ रोस्ट बीफ़","लाल प्याज़ का 1 स्लाइस","1/4 लाल शिमला मिर्च","खीरे के 4 स्लाइस","रोमेन लेट्यूस का 1 पत्ता","1 मैदा की टॉर्टिला, 6-इंच","1 बड़ा चम्मच व्हिप्ड क्रीम चीज़","1/2 छोटा चम्मच Mrs. Dash हर्ब सीज़निंग ब्लेंड","1/2 कप अंगूर","10 बादाम, बिना नमक के"],
["रोस्ट बीफ़ और खीरे को स्लाइस में काटें; प्याज़ और शिमला मिर्च को काट लें। रोमेन लेट्यूस के पत्ते की मोटी नस निकाल दें।","बीफ़ रोलअप तैयार करने के लिए टॉर्टिला पर क्रीम चीज़ फैलाएँ। उस पर रोस्ट बीफ़ के स्लाइस और सब्ज़ियों की परत लगाएँ। हर्ब सीज़निंग छिड़कें।","टॉर्टिला को जेली रोल की तरह लपेटें और 4 टुकड़ों में काट लें।","रोलअप, अंगूर और बादाम को एक प्लेट में या खानों वाले लंच कंटेनर में रखें।"],
["पेय के सुझाव: नींबू पानी, फ्लेवर्ड स्पार्कलिंग वाटर, लेमन-लाइम सोडा, ताज़ी बनी चाय या कॉफ़ी।","सफ़र में भोजन के लिए, लंच बॉक्स को आइस पैक के साथ पैक करें ताकि खाने तक भोजन ठंडा रहे।"],["3 मांस","1 स्टार्च","1 सब्ज़ी, कम पोटैशियम","1 फल, कम पोटैशियम"]))
R.append(T(3019,"मांस और चावल के गोले","मांस और चावल के गोले इस स्वादिष्ट किडनी-अनुकूल रेसिपी का असली नाम नहीं है। बीफ़ और चावल के इन मीटबॉल का उपनाम पोर्क्यूपाइन बॉल्स (साही के गोले) रखा गया था क्योंकि चावल साही के काँटों की तरह ऊपर निकले रहते हैं। यह रेसिपी मिसौरी के DaVita रीनल आहार विशेषज्ञ केन की है, और यह परिवार की पुरानी पसंदीदा रेसिपी है जिसे सालों से आज़माया और परखा गया है।","4","3 औंस या 6 मीटबॉल",
["1 पाउंड कम चर्बी वाला कीमा बीफ़","1 बड़ा अंडा","1 कप इंस्टेंट सफेद चावल","3/4 छोटा चम्मच Mrs. Dash® हर्ब सीज़निंग ब्लेंड","2-1/4 कप पानी"],
["एक बड़े कटोरे में कीमा बीफ़, अंडा और चावल मिलाएँ।","अच्छी तरह मिल जाने के बाद 24 छोटे गोले बना लें।","गोलों को स्किलेट में चारों तरफ से भूरा करें।","Mrs. Dash® हर्ब सीज़निंग को पानी में मिलाएँ।","पानी और Mrs. Dash के मिश्रण को सावधानी से मीटबॉल वाली स्किलेट में डालें।","पानी में उबाल आने दें।","ढककर 20 से 30 मिनट तक धीमी आँच पर पकाएँ, गोलों को सभी तरफ से पलटते रहें।"],
["कम वसा वाले व्यंजन के लिए कीमा बीफ़ की जगह कीमा टर्की का उपयोग करें।","यदि आप कम प्रोटीन वाला आहार ले रहे हैं, तो अपनी भोजन योजना के अनुसार मात्रा समायोजित करें।"],["3 मांस","1 स्टार्च","1 वसा"]))
R.append(T(3020,"चीज़ी ग्रिट्स","तीखे चीज़ का अतिरिक्त स्वाद इस व्यंजन को चीज़ी बनाता है, फिर भी यह किडनी-अनुकूल है। चीज़ी ग्रिट्स को नाश्ते में अंडों के साथ या रात के खाने में झींगे के साथ आज़माएँ।","2","3/4 कप (गाढ़ा हो तो 2/3 कप)",
["1 कप पानी","1/2 कप 2% कम वसा वाला दूध","1/8 छोटा चम्मच नमक (वैकल्पिक)","1/3 कप सफेद या पीली ग्रिट्स","2 छोटे चम्मच बिना नमक का मक्खन","4 बड़े चम्मच कद्दूकस किया हुआ तीखा चेडर चीज़"],
["एक मध्यम पैन में पानी, दूध और नमक को मध्यम-तेज़ आँच पर उबाल आने तक गरम करें।","ग्रिट्स डालकर चलाएँ। आँच धीमी करें और पैन को ढक्कन से आंशिक रूप से ढक दें। चिकनी ग्रिट्स के लिए बार-बार चलाएँ।","पारंपरिक ग्रिट्स को 15 से 20 मिनट पकाएँ, या जल्दी पकने वाली ग्रिट्स को 8 से 9 मिनट।","पैन को आँच से उतारें और मक्खन मिलाएँ।","2 हिस्सों में बाँटें और हर हिस्से के ऊपर 2 बड़े चम्मच कद्दूकस किया हुआ चीज़ डालें। चीज़ को मिलाएँ और गरम परोसें।"],
["तीखा या अतिरिक्त तीखा चेडर चीज़ कम मात्रा में इस्तेमाल करने पर भी अधिक चीज़ी स्वाद देता है। और अधिक चीज़ी स्वाद तथा B विटामिन बढ़ाने के लिए, पकाने के आखिरी 5 मिनट में 1 से 2 बड़े चम्मच न्यूट्रिशनल यीस्ट मिलाएँ।","गाढ़ी ग्रिट्स के लिए सूखी ग्रिट्स की मात्रा बढ़ाकर 1/2 कप कर दें।","इंस्टेंट ग्रिट्स से बचें। उनमें प्रति सर्विंग सोडियम 340 से 520 mg तक होता है।","गाय के दूध की जगह बादाम, चावल या सोया दूध जैसे बिना मीठे दूध के विकल्प इस्तेमाल किए जा सकते हैं।"],["1 स्टार्च","1 दूध","1 वसा"]))
R.append(T(3023,"बफ़ेलो चिकन डिप","बफ़ेलो चिकन में गरम और तीखे बफ़ेलो विंग्स का पूरा स्वाद है, जो क्रीम चीज़ और खट्टी क्रीम से भरे चिकने और लाजवाब डिप में मिलता है। और क्योंकि यह डिप किडनी-अनुकूल है, इसलिए आपका पूरा परिवार, दोस्त और सहकर्मी सभी इसका आनंद ले सकते हैं।","16","1/4 कप",
["4 औंस कम वसा वाला क्रीम चीज़","1/2 कप बोतल में बंद भुनी हुई लाल शिमला मिर्च","1 कप कम वसा वाली खट्टी क्रीम (सावर क्रीम)","4 छोटे चम्मच Tabasco® हॉट पेपर सॉस","2 कप पका हुआ, रेशे-रेशे किया हुआ चिकन"],
["क्रीम चीज़ को नरम होने के लिए बाहर रख दें।","लाल शिमला मिर्च का पानी निथारें और 1/2 कप नाप लें। ब्लेंडर या फ़ूड प्रोसेसर में प्यूरी करके लाल मिर्च का सॉस बना लें।","एक मध्यम कटोरे में क्रीम चीज़ और खट्टी क्रीम को चिकना होने तक मिलाएँ। प्यूरी की हुई शिमला मिर्च और 2 छोटे चम्मच Tabasco सॉस डालें। मिलने तक चलाएँ।","चिकन डालकर धीरे से मिलाएँ। 1/2 छोटा चम्मच करके और हॉट सॉस डालें; चखें और अपनी मनचाही तीखेपन तक हॉट सॉस डालते रहें।","मिश्रण को स्लो कुकर में धीमी आँच पर 2 से 3 घंटे रखें, या ओवन में 350° F पर 30 मिनट बेक करें।","गरम डिप को डुबोने के लिए गाजर, सेलरी, खीरे, फूलगोभी के साथ परोसें, या डिप को सलाद या पत्ता गोभी के पत्तों में लपेटकर छोटे रोल-अप बनाएँ।"],
["ऐसी बोतलबंद या डिब्बाबंद भुनी लाल शिमला मिर्च देखें जिसमें प्रति औंस 85 mg या उससे कम सोडियम हो, या ताज़ी लाल शिमला मिर्च को भूनकर प्यूरी बनाएँ। Trader Joe’s की फायर रोस्टेड लाल शिमला मिर्च में प्रति औंस केवल 60 mg सोडियम होता है।","यदि उपलब्ध हो तो जमी हुई भुनी लाल शिमला मिर्च भी इस्तेमाल की जा सकती है।","हॉट सॉस के ब्रांड और किस्मों में सोडियम की मात्रा बहुत अलग-अलग होती है। मूल Tabasco® हॉट पेपर सॉस ही लें क्योंकि उसमें सोडियम काफ़ी कम होता है। यदि आपको अधिक तीखा पसंद है तो इसे बढ़ाकर 6 छोटे चम्मच कर दें।","कच्ची सब्ज़ियों के साथ परोसें। कम पोटैशियम वाले विकल्पों में डुबोने के लिए गाजर, सेलरी, खीरा, फूलगोभी, या रैप के लिए सलाद या पत्ता गोभी के पत्ते शामिल हैं।","यदि पार्टी में परोस रहे हैं, तो बेक करने के बाद गरम रखने के लिए इसे छोटे स्लो कुकर में रखें।"],["1 मांस"]))
R.append(T(3024,"घर का बना चिकन और डम्पलिंग (या टर्की)","आज फास्ट और सुविधाजनक भोजन की हमारी दुनिया में हम भूल सकते हैं कि बुनियादी सामग्री से बना सादा भोजन आमतौर पर अधिक स्वादिष्ट और संतोषजनक होता है। टेक्सास की DaVita रीनल आहार विशेषज्ञ डोना घर के बने चिकन और डम्पलिंग की अपनी देसी रेसिपी साझा करती हैं और आपको इस भोजन को अपने सेहतमंद रीनल आहार में शामिल करने के लिए आमंत्रित करती हैं। यह एक ऐसी रेसिपी है जिसका आप अनुसरण कर सकते हैं, जो बेहद स्वादिष्ट होगी और आपको डायलिसिस आहार में सफल रखेगी।","8","1-1/4 कप",
["5 पाउंड का रोस्टिंग चिकन, टुकड़ों में कटा हुआ","6 कप पानी","1/2 कप सेलरी, छोटे टुकड़ों में कटी","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच Mrs. Dash® हर्ब सीज़निंग ब्लेंड","3 कप आलू, छीलकर 1/4” मोटे स्लाइस में कटे हुए","1 मध्यम प्याज़, कटा हुआ","1 कप मैदा","1 बड़ा चम्मच मक्खन, नरम किया हुआ","1 अंडा, हल्का फेंटा हुआ","3 बड़े चम्मच कटा हुआ ताज़ा अजमोद (पार्सले)"],
["आलू छीलकर स्लाइस में काटें। कुछ पोटैशियम निकालने के लिए उन्हें एक बड़े बर्तन के पानी में 3-4 घंटे भिगोएँ, या आलू को 5 मिनट उबालें, पानी निथार दें, फिर ताज़ा पानी डालकर नरम होने तक पकाएँ। चिकन या टर्की के टुकड़ों को 6 कप पानी के साथ डच ओवन में रखें। सेलरी, नमक, काली मिर्च और हर्ब सीज़निंग डालें। उबाल आने दें। आँच कम करें और ढककर 60 मिनट या नरम होने तक धीमी आँच पर पकाएँ। मांस को हड्डियों से अलग करके एक तरफ रख दें।","भिगोए हुए या दो बार उबाले हुए आलू और प्याज़ को शोरबे में डालें। शोरबे में उबाल आने दें और आलू के नरम होने तक, लगभग 15 मिनट पकाएँ। सब्ज़ियों को छेद वाली करछी से निकालकर एक तरफ रख दें।","एक बड़े कटोरे में मैदा और मक्खन को काँटे से मिलाएँ। अंडा और 2 बड़े चम्मच पानी डालें; सामग्री के नम होने तक काँटे से मिलाएँ।","आटे को 1/3” मोटा बेलें। तेज़ चाकू से आटे को पट्टियों में काटें।","नूडल की पट्टियों को शोरबे में डालें और 15 मिनट तक पकाएँ (यदि पहले से पैक किए गए डम्पलिंग नूडल्स इस्तेमाल कर रहे हैं, तो उन्हें इसी समय शोरबे में डाल दें।)","सब्ज़ियाँ और मांस शोरबे में डालें और 5 मिनट धीमी आँच पर पकाएँ।","ताज़ा अजमोद छिड़कें और परोसें।"],
["सुविधा के लिए आप Mary B’s® ब्रांड जैसे तैयार डम्पलिंग नूडल्स का पैकेट इस्तेमाल कर सकते हैं, जो आपके किराना स्टोर के फ्रोज़न फ़ूड सेक्शन में मिल जाता है।","यदि आप प्रोटीन-नियंत्रित आहार ले रहे हैं, तो प्रति सर्विंग प्रोटीन को 21 ग्राम तक घटाने के लिए 2.5 पाउंड का छोटा चिकन चुनें।","चिकन की जगह 3 टर्की की टाँगें, जिनकी त्वचा और हड्डियाँ हटाकर काटा गया हो, इस्तेमाल करें।"],["4 मांस","1-1/2 स्टार्च","1/2 सब्ज़ी, मध्यम पोटैशियम"]))
R.append(T(3027,"टेरियाकी टेम्पे वेजिटेबल बाउल","टेम्पे किण्वित सोयाबीन है। यह आम तौर पर सोडियम में कम होता है और प्रोटीन का बेहतरीन स्रोत है। आप इसे टुकड़ों में, स्लाइस में या चूरा करके और अपने पसंदीदा व्यंजन में मांस की जगह डालकर रचनात्मक बन सकते हैं।","4","1/3 कप चावल, 2 औंस टेम्पे, सब्ज़ियों का 1/4 हिस्सा",
["8 औंस का टेम्पे पैकेट","1 बड़ा चम्मच ऑलिव ऑयल","2/3 कप ब्राउन राइस","1/4 कप कोकोनट अमीनो","1/4 कप पानी + 4 छोटे चम्मच, बँटा हुआ","1/4 कप शहद","1 बड़ा चम्मच राइस विनेगर","2 छोटे चम्मच कॉर्नस्टार्च","12.6 औंस का जमे हुए ब्रोकली का बैग","1 हरा प्याज़ (स्कैलियन), वैकल्पिक"],
["टेम्पे को आड़ी दिशा में 12 छोटी पट्टियों में काटें। पैन में ऑलिव ऑयल गरम करें और टेम्पे डालें। 8-10 मिनट तक पकाएँ और पलटते रहें जब तक वह भूरा होना शुरू न हो जाए।","चावल को पैकेट पर दिए निर्देशों के अनुसार पकाएँ, उपयोगी सुझाव देखें।","एक छोटे सॉसपैन में कोकोनट अमीनो, 1/4 कप पानी, शहद और राइस विनेगर को फेंटकर मिलाएँ और उबाल आने दें। इस बीच कॉर्नस्टार्च और 4 छोटे चम्मच पानी मिलाएँ। इसे उबलते सॉस में डालें और गाढ़ा होना शुरू होने तक फेंटते रहें।","सॉस को सॉसपैन में टेम्पे के ऊपर डालें और 5-8 मिनट तक अच्छी तरह गरम करें।","ब्रोकली को माइक्रोवेव में भाप में पकाएँ। ज़रूरत हो तो पानी निथार लें और एक तरफ रख दें।","चावल को 4 कटोरों में बाँटें, हर कटोरे में लगभग 1/3 कप। हर कटोरे में ब्रोकली (1/2 कप) डालें और ऊपर टेम्पे के 3 स्लाइस रखें। हर कटोरे पर 2 बड़े चम्मच क्रेमा छिड़कें। चाहें तो हरे प्याज़ को काटकर हर कटोरे पर छिड़कें।"],
["इंस्टेंट ब्राउन राइस इस्तेमाल किया गया। पकाने के लिए 1-1/3 कप पानी लिया, उबाल आने दिया और फिर ढककर 10 मिनट धीमी आँच पर पकाया।","12.6 औंस के स्टीमर वेजिटेबल बैग से लगभग 2 कप सब्ज़ियाँ मिलती हैं।","टेम्पे में स्वाभाविक रूप से सोडियम कम होता है। फिर भी, ब्रांड की तुलना करते समय सबसे कम सोडियम वाला ब्रांड ही चुनें। यदि वह मैरिनेट किया हुआ न हो तो सोडियम की मात्रा बहुत कम होनी चाहिए।","क्रेमा ड्रेसिंग वैकल्पिक रूप से डाली जा सकती है। 4 बड़े चम्मच खट्टी क्रीम को 3 बड़े चम्मच पानी के साथ मिलाएँ। इससे प्रति सर्विंग 15 mg पोटैशियम और 9 mg फॉस्फोरस बढ़ेगा।"],["1-1/2 प्रोटीन","1 स्टार्च","1 सब्ज़ी, कम पोटैशियम","1 वसा","1 उच्च कैलोरी"]))
R.append(T(3028,"रास्पबेरी-नींबू फ्लेवर्ड पानी","पानी किडनी के मरीज़ों के लिए सबसे सेहतमंद पेय पदार्थों में से एक है, लेकिन यह ज़रूरी नहीं कि वह सादा और बेस्वाद ही हो! DaVita की आहार विशेषज्ञ कारा की कई फ्लेवर्ड पानी रेसिपी में से एक, रास्पबेरी-नींबू फ्लेवर्ड पानी आज़माएँ।","10","1 कप (8 औंस)",
["1 नींबू (लाइम)","12 पुदीने की पत्तियाँ","1/2 कप ताज़ी रास्पबेरी","10 कप पानी"],["नींबू को पतले स्लाइस में काटें।","पुदीने की पत्तियों को बारीक काटें।","सभी सामग्री एक जग में डालें।","परोसने से पहले रात भर फ्रिज में रखें।"],
["फ्लेवर्ड पानी के हर कप में कुछ बेरियाँ डालें।","विविधता के लिए रास्पबेरी की जगह स्ट्रॉबेरी आज़माएँ।","यदि आप तरल पदार्थ सीमित मात्रा में लेते हैं, तो अपनी ज़रूरत के अनुसार मात्रा को समायोजित करें।","स्वाद आ जाने के बाद आप इसे आइस क्यूब ट्रे में डालकर फ्लेवर्ड बर्फ बना सकते हैं।"],["कोई नहीं"]))
R.append(T(3029,"मध्य-पूर्वी मसाला मिश्रण","अपने मांस, पोल्ट्री या चावल के लिए यह मध्य-पूर्वी मसाला मिश्रण बनाएँ, ताकि बिना अतिरिक्त नमक के स्वाद बढ़ सके।","12","1 बड़ा चम्मच",
["1 बड़ा चम्मच पिसा धनिया","1 बड़ा चम्मच पिसा जीरा","1 बड़ा चम्मच हल्दी","2 छोटे चम्मच कुटी हुई पुदीने की पत्तियाँ","1 छोटा चम्मच पिसी दालचीनी"],["सामग्री को एक जार में डालें और मिलाने के लिए हिलाएँ।","उपयोग के समय तक रखें।"],
["मांस, पोल्ट्री या चावल में मसाले के रूप में इस्तेमाल करें।","अपने स्वाद के अनुसार मात्रा समायोजित करें।"],["कोई नहीं"]))
R.append(T(3030,"पास्ता प्रिमावेरा","पास्ता प्रिमावेरा बड़े समूह के लिए बनाने की एक बेहतरीन किडनी-अनुकूल रेसिपी है।","6","1-3/4 कप",
["12 औंस पास्ता, बिना पका","12 औंस जमी हुई मिश्रित सब्ज़ियाँ","14 औंस कम सोडियम वाला चिकन शोरबा","2 बड़े चम्मच मैदा","1/4 कप हाफ एंड हाफ क्रीमर","1/4 छोटा चम्मच लहसुन पाउडर","1/4 कप कद्दूकस किया हुआ पार्मेसन चीज़"],
["पास्ता और सब्ज़ियों को अलग-अलग बर्तनों में पैकेट के निर्देशों के अनुसार पकाएँ, लेकिन नमक न डालें। पानी निथार दें।","कम सोडियम वाला चिकन शोरबा एक मध्यम आकार के स्टॉकपॉट में डालें और धीमी आँच पर गरम करें।","गाँठें न बनें, इसलिए शोरबे में मैदा डालकर ज़ोर से फेंटें।","हाफ एंड हाफ और लहसुन पाउडर डालकर चलाएँ।","धीमी आँच पर 5 से 10 मिनट तक पकाएँ जब तक मिश्रण थोड़ा गाढ़ा न हो जाए। पकाते समय बीच-बीच में चलाएँ।","पकी हुई सब्ज़ियाँ और पास्ता डालें। गरम होने तक पकाएँ।","पार्मेसन चीज़ छिड़कें और परोसें।"],
["जमी हुई सब्ज़ियों के मिश्रण में पोटैशियम की मात्रा अलग-अलग होती है। कम पोटैशियम वाली सब्ज़ियों का मिश्रण चुनें, या यदि आप पोटैशियम सीमित कर रहे हैं तो अपने आहार विशेषज्ञ से अपने आहार के लिए सबसे अच्छे विकल्प पूछें।","12 औंस बिना पका पास्ता लगभग 6 कप पके हुए पास्ता के बराबर होता है।"],["3 स्टार्च","1 सब्ज़ी, कम पोटैशियम"]))
R.append(T(3031,"ज़ुकिनी पैनकेक","ज़ुकिनी पैनकेक क्रोनिक किडनी रोग (CKD) वाले लोगों के लिए सब्ज़ियाँ खाने का एक रचनात्मक और झटपट तरीका है। हैश ब्राउन जैसी बनावट वाली इस रेसिपी में स्वादिष्ट ज़ुकिनी के स्लाइस, चटपटा प्याज़ और सबको जोड़े रखने वाले अंडे शामिल हैं। इस सब्ज़ी के व्यंजन का आनंद 1 बड़े चम्मच सेब की प्यूरी या क्रैनबेरी सॉस के साथ लें। यह ज़रूर पसंदीदा बन जाएगा!","4","1 पैनकेक",
["2 कप ज़ुकिनी","1/4 कप प्याज़","1 बड़ा चम्मच मैदा","1 छोटा चम्मच Mrs. Dash® ओरिजिनल ब्लेंड हर्ब सीज़निंग","1/4 कप तरल कम कोलेस्ट्रॉल वाला अंडे का विकल्प","1 बड़ा चम्मच कैनोला तेल","1/8 छोटा चम्मच नमक"],
["प्याज़ और ज़ुकिनी को एक कटोरे में कद्दूकस करें और मिलाएँ। ज़ुकिनी के मिश्रण को साफ रसोई के तौलिये पर रखें। मरोड़कर और निचोड़कर जितना हो सके उतना तरल निकाल दें। वापस कटोरे में डालें।","एक छोटे कटोरे में मैदा, नमक और Mrs. Dash® हर्ब सीज़निंग मिलाएँ। अंडे का विकल्प डालकर मिलाएँ; इसे ज़ुकिनी और प्याज़ के मिश्रण में मिलाएँ। 4 टिक्कियाँ बनाएँ।","एक बड़े नॉनस्टिक फ्राइंग पैन में तेज़ आँच पर तेल गरम करें। आँच मध्यम करें और ज़ुकिनी की टिक्कियाँ पैन में रखें। भूरा होने तक भूनें, एक बार पलटें।"],
["1 बड़े चम्मच सेब की प्यूरी या क्रैनबेरी सॉस के साथ परोसें।"],["1 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]))
R.append(T(3032,"बेक्ड डोनट","घर पर डोनट बनाना एक संतोषजनक अनुभव है। DaVita की आहार विशेषज्ञ रॉबिन की बेक्ड डोनट रेसिपी में प्रोटीन बढ़ाने के साथ फाइबर बढ़ाने के लिए साबुत गेहूँ का आटा भी शामिल है।","12","1 डोनट या 4 डोनट होल",
["5 बड़े चम्मच बिना नमक का मक्खन","1/4 कप कैनोला तेल","1/4 कप दानेदार चीनी","1/3 कप दबाकर भरी हुई ब्राउन शुगर","2 बड़े अंडे","1-1/2 छोटा चम्मच बेकिंग पाउडर","1/4 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच जायफल","1/2 छोटा चम्मच नमक","1-1/2 छोटा चम्मच वनीला एक्सट्रैक्ट","2 कप साबुत गेहूँ का पेस्ट्री आटा","2/3 कप मैदा","1/4 कप वनीला प्रोटीन पाउडर","1 कप सादा ग्रीक योगर्ट","1/4 कप दूध + 1 से 2 बड़े चम्मच","1-1/4 कप छनी हुई कन्फेक्शनर्स शुगर (पिसी चीनी)","1 बड़ा चम्मच हल्के रंग का कॉर्न सिरप","1/4 कप स्प्रिंकल्स"],
["ओवन को 425° F पर पहले से गरम करें। 2 मानक डोनट पैन (12 डोनट) पर हल्की चिकनाई लगाएँ।","एक मध्यम कटोरे में इलेक्ट्रिक मिक्सर से 4 बड़े चम्मच मक्खन, तेल, दानेदार चीनी और ब्राउन शुगर को चिकना होने तक फेंटें।","अंडे डालकर मिलाने के लिए फेंटें।","बेकिंग पाउडर, बेकिंग सोडा, जायफल, नमक और 1 छोटा चम्मच वनीला मिलाएँ।","आटे और प्रोटीन पाउडर को मक्खन के मिश्रण में बारी-बारी से योगर्ट और दूध के साथ मिलाएँ। आटे के मिश्रण से शुरू करें और उसी पर खत्म करें। सुनिश्चित करें कि सब कुछ अच्छी तरह मिल जाए। घोल काफ़ी","गाढ़ा होगा। जब आप घोल में स्पैचुला चलाएँगे, तो उसे एक निशान छोड़ना चाहिए।","घोल को हल्की चिकनाई लगे डोनट पैन में चम्मच से डालें, ऊपर से लगभग 1/4 इंच खाली छोड़ें। वैकल्पिक रूप से आप पाइपिंग बैग से घोल को डोनट पैन में डाल सकते हैं।","डोनट को 10 मिनट बेक करें। पैन को ओवन से निकालें और डोनट को 5 से 7 मिनट ठंडा होने दें। डोनट को पैन से निकालें और पूरी तरह ठंडा होने दें।","डोनट के ठंडा होने के दौरान ग्लेज़ बनाएँ। एक उथले कटोरे में छनी हुई कन्फेक्शनर्स शुगर, कॉर्न सिरप, बचा हुआ वनीला, (पिघला हुआ) मक्खन और 1 बड़ा चम्मच दूध मिलाएँ। गाढ़ाई को ठीक करने के लिए ज़रूरत के अनुसार अतिरिक्त दूध या","कन्फेक्शनर्स शुगर डालें।","स्प्रिंकल्स को अलग उथले कटोरे में डालें।","डोनट के ऊपरी हिस्से को ग्लेज़ में डुबोकर परत चढ़ाएँ, फिर स्प्रिंकल्स में डुबोएँ। जमने के लिए जाली पर रखें।"],
["आप घोल को मिनी मफ़िन टिन में भी बेक कर सकते हैं, फिर ग्लेज़ और स्प्रिंकल्स लगाकर “डोनट होल” बना सकते हैं।","यदि साबुत गेहूँ का पेस्ट्री आटा उपलब्ध न हो, तो 1 कप साबुत गेहूँ का आटा और 1 कप मैदा (2/3 कप मैदा के अतिरिक्त) इस्तेमाल करें।","बेकरी के डोनट की तुलना में इस रेसिपी में प्रोटीन और फाइबर अधिक तथा सोडियम कम है।"],["1-1/2 स्टार्च","1/2 दूध","2 वसा","1-1/2 उच्च कैलोरी"]))
R.append(T(3035,"काराओवे राई ब्रेड","खमीर वाली ब्रेड बेक करना एक कला है। DaVita की आहार विशेषज्ञ तारा की काराओवे राई ब्रेड रेसिपी से अपने अंदर के कलाकार को बाहर लाएँ। यह कम सोडियम और भरपूर स्वाद वाली है!","16","1 स्लाइस",
["2 कप राई का आटा","1-1/2 कप मैदा","1 छोटा चम्मच कोशर नमक","1 छोटा चम्मच एक्टिव ड्राई यीस्ट","1-1/2 कप गुनगुना पानी","2 छोटे चम्मच काराओवे बीज"],
["स्टैंड मिक्सर में आटा, नमक, यीस्ट और काराओवे बीज मिलाएँ।","आटे के मिश्रण के बीच में गड्ढा बनाएँ और गुनगुना पानी डालें।","आटा गीला और चिपचिपा होने तक मिलाएँ।","प्लास्टिक रैप से ढकें और 3 घंटे तक गरम, सूखी जगह पर रखें।","ओवन को 450° F पर गरम करें। एक एनामेल डच ओवन को ढक्कन सहित ओवन में रखें। 30 मिनट तक गरम होने दें।","डच ओवन के गरम होने के दौरान, आटे को कटोरे से खुरचकर निकालें और आटा लगे बोर्ड या काउंटरटॉप पर रखें।","अपने हाथों पर आटा लगाएँ और आटे को कुछ बार मोड़ें; आटे का गोला बनाएँ। जोड़ वाला हिस्सा आटे के नीचे की तरफ रखें।","डच ओवन को ओवन से सावधानी से निकालें और आटा उसके अंदर रखें। ढक्कन वापस लगाएँ और ओवन में रखें। 30 मिनट या ब्रेड का आंतरिक तापमान 200° F तक पहुँचने तक बेक करें।","ओवन से निकालें और ठंडा करने की जाली पर रखें। ठंडी हुई ब्रेड को 16 टुकड़ों में काटें।"],
["अधिक कुरकुरी परत के लिए डच ओवन का ढक्कन हटाकर अतिरिक्त 10 मिनट बेक कर सकते हैं।","यह रेसिपी डच ओवन में सबसे अच्छी बनती है। लोफ पैन की सलाह नहीं दी जाती।"],["1 स्टार्च"]))
R.append(T(3036,"चटपटा खीरा सलाद","यह सरल किडनी-अनुकूल रेसिपी खीरे, इटैलियन ड्रेसिंग और लाल प्याज़ के स्वाद से भरपूर है। इसीलिए चटपटा खीरा सलाद रात के खाने की मेज़ पर एक से अधिक बार दिखेगा।","14","1/2 कप",
["5 कप खीरे","2 कप लाल प्याज़","1/2 कप Kraft® Light Done Right!® इटैलियन सलाद ड्रेसिंग","1/4 कप चीनी"],
["खीरे छीलकर उनके बीज निकालें; प्याज़ को स्लाइस में काटें।","सभी सामग्री को एक बड़े कटोरे में मिलाएँ।","ढककर कम से कम 30 मिनट मैरिनेट करने के लिए फ्रिज में रखें।","ठंडा परोसें।"],
["चीनी की जगह चीनी का विकल्प इस्तेमाल करके कार्बोहाइड्रेट को 4 ग्राम तक घटाएँ।","बचा हुआ सलाद फ्रिज में एक सप्ताह तक ठीक रहेगा।"],["1 सब्ज़ी, कम पोटैशियम"]))
R.append(T(3037,"बेसिल पेस्टो","इस बेसिल पेस्टो में मिली सब्ज़ियों की एक सर्विंग का आनंद लें। यह पास्ता में मिलाने, या समुद्री भोजन या चिकन के लिए मैरिनेड या टॉपिंग के रूप में बेहतरीन है। इस रचनात्मक रेसिपी में चीज़ की जगह न्यूट्रिशनल यीस्ट का उपयोग किया गया है।","12","2 बड़े चम्मच",
["2 कप ताज़ी तुलसी की पत्तियाँ","2/3 कप न्यूट्रिशनल यीस्ट","लहसुन की 3 कलियाँ","1/2 ताज़ा नींबू","1 छोटा चम्मच काली मिर्च","1 कप चिलगोज़े (पाइन नट्स)","2 बड़े चम्मच अलसी का तेल","2 बड़े चम्मच ऑलिव ऑयल"],
["नींबू का रस निचोड़ें। अलसी और ऑलिव ऑयल को छोड़कर सभी सामग्री फ़ूड प्रोसेसर में डालें।","तेलों को मिलाएँ और सामग्री को पीसते समय तेल को ऊपर से फ़ूड प्रोसेसर में डालें ताकि वह समान रूप से घुल जाए। ज़रूरत पड़ने पर ब्लेंडर के तले से सामग्री को चलाएँ।","पेस्टो को मैरिनेड, सलाद ड्रेसिंग या पास्ता सॉस के रूप में उपयोग के समय तक जार या ढके हुए डिब्बे में रखें। फ्रिज में एक सप्ताह तक चलता है।"],
["ऑलिव ऑयल की जगह अतिरिक्त 2 बड़े चम्मच अलसी का तेल इस्तेमाल किया जा सकता है।","अलसी का तेल ALA ओमेगा-3 फैटी एसिड देने सहित सेहत संबंधी लाभ प्रदान करता है।","बेसिल पेस्टो बहुत बहुमुखी है; इसे समुद्री भोजन या चिकन पर मैरिनेड के रूप में, ताज़ी या भुनी सब्ज़ियों के लिए डिपिंग सॉस के रूप में, सलाद ड्रेसिंग के रूप में इस्तेमाल करें, या टमाटर की सॉस के कम पोटैशियम वाले विकल्प के रूप में पास्ता या चावल में मिलाएँ।"],["1 सब्ज़ी, मध्यम पोटैशियम","2 वसा"]))
R.append(T(3038,"चिकन के साथ करी सॉस","कैलिफ़ोर्निया की DaVita रीनल आहार विशेषज्ञ कैरेन किडनी आहार में एक भरपूर करी सॉस के साथ मसाले का तड़का लगाती हैं, जिसे समुद्री भोजन, चिकन या बीफ़ के साथ परोसा जा सकता है। बिना चीनी की और कम सोडियम वाले शोरबे से बनी यह सॉस किडनी रोग का प्रबंधन करने वाले लोगों के लिए एकदम सही है। कैरेन की करी सॉस बहुमुखी, किडनी-अनुकूल और मांस में तीखापन जोड़ने का बेहतरीन तरीका है।","6","1-1/2 कप",
["लहसुन की 1 कली","1 छोटा चम्मच अदरक","1/3 कप गाजर","1/3 कप सेलरी","1/3 कप प्याज़","1 छोटा सेब","8 औंस मशरूम","3 बड़े चम्मच मैदा","2 बड़े चम्मच करी पाउडर","4 बड़े चम्मच वनस्पति तेल","32 औंस कम सोडियम वाला चिकन स्टॉक","1/2 छोटा चम्मच सफेद मिर्च","1-1/2 पाउंड बिना हड्डी का चिकन"],
["लहसुन और अदरक को बारीक काटें। गाजर, सेलरी और प्याज़ को बारीक काटें। मशरूम को स्लाइस में काटें। सेब को काट लें।","मैदा, लहसुन, अदरक, करी पाउडर और वनस्पति तेल को एक नॉन-स्टिक, गहरी स्किलेट (कम से कम 4 क्वार्ट) में मध्यम आँच पर मिलाएँ।","चलाएँ जब तक करी पेस्ट जैसी न हो जाए।","धीरे-धीरे शोरबा डालें और सॉस के चिकना होने तक चलाएँ।","सब्ज़ियाँ, सेब और सफेद मिर्च डालें।","लगातार चलाते हुए 15 मिनट तक या अच्छी तरह मिलने तक धीमी आँच पर पकाएँ।","सॉस में उबाल आने दें और चिकन डालें।","करी को धीमी आँच पर 1-1/2 घंटे तक पकाएँ, नियमित रूप से चलाते रहें और परोसें।"],
["समय बचाने के लिए Trader Joe’s® मिरपुआ मिक्स का उपयोग करें, जो गाजर, सेलरी और प्याज़ का पहले से कटा और धुला हुआ डिब्बा होता है।","विविधता के लिए चिकन की जगह बीफ़ या समुद्री भोजन इस्तेमाल करें। यदि कच्चे बीफ़ का उपयोग कर रहे हैं, तो चरण 6 में करी में डालने से पहले उसे भूरा कर लें।","कम प्रोटीन वाले आहार पर बिना डायलिसिस वाले CKD मरीज़ों के लिए, मात्रा घटाकर 3/4 कप कर दें।","पूरे भोजन के लिए चावल के ऊपर परोसें।"],["4 मांस","1/2 सब्ज़ी, मध्यम पोटैशियम"]))
save(3,R)
